let readingFrame=0;function updateReading(){if(readingFrame)return;readingFrame=requestAnimationFrame(()=>{readingFrame=0;const total=document.documentElement.scrollHeight-innerHeight;const percent=Math.max(0,Math.min(100,total>0?(scrollY+innerHeight>=document.documentElement.scrollHeight-2?100:Math.floor(scrollY/total*100)):100));document.getElementById('reading-percent').textContent=percent+'%';document.getElementById('reading-fill').style.height=percent+'%';document.getElementById('reading-lion').style.top=percent+'%';document.getElementById('reading-progress').setAttribute('aria-valuenow',percent);celebrateReading(percent);});}addEventListener('scroll',updateReading,{passive:true});addEventListener('resize',updateReading,{passive:true});if(typeof ResizeObserver!=='undefined')new ResizeObserver(updateReading).observe(document.querySelector('main'));updateReading();
